if(refinement.kind === "record") return refinement.arguments.flatMap((child, index) =>
	constructorRefinementLeaves(child, type.fields[index].type, `${suffix}_${index}`));
if(refinement.kind === "variant") return refinement.cases.flatMap((branch, index) => branch.arguments.flatMap((child, field) =>
	constructorRefinementLeaves(child, type.cases[index].fields[field].type, `${suffix}_${index}_${field}`)));

const containsSubtype = refinement => refinement?.kind === "subtype"
	|| (refinement?.arguments ?? []).some(containsSubtype)
	|| (refinement?.cases ?? []).some(branch => branch.arguments.some(containsSubtype));

/**
 * Share Fin-only checks, but key constructor-bearing conversions by the complete site tree.
 * Field/case order, nested choices and bounds are part of that identity.
 *
 * @param refinement - A validated record or variant refinement tree.
 */
export const nominalRefinementCheck = refinement => containsSubtype(refinement)
	? `via_${sha256(canonicalJson(refinement))}` : "check";

if(refinement.kind === "subtype")
{
	if(checked && typeof refinement.constructor !== "string") throw new TypeError("A Subtype input requires its site's constructor");
	return checked ? `_root_.${refinement.constructor} ${value}` : `${input}.val`;
}

const trees = new Map(), layouts = new Map(), checks = new Map(), constructors = new Map();
// Constructor choices change how a source value is built, never its payload layout or erasure.
const layout = tree => tree?.kind === "subtype" ? { kind: "subtype" }
	: tree?.kind === "variant" ? { ...tree, cases: tree.cases.map(branch => ({ ...branch, arguments: branch.arguments.map(layout) })) }
		: tree?.arguments ? { ...tree, arguments: tree.arguments.map(layout) } : tree;
const walk = (tree, checked) => {

if(["record", "variant"].includes(tree.kind))
{
	const key = canonicalJson(layout(tree));
	if(layouts.has(tree.definition) && layouts.get(tree.definition) !== key)
		throw new TypeError(`Conflicting nominal refinement layouts: ${tree.definition}`);
	layouts.set(tree.definition, key);
	if(!trees.has(tree.definition)) trees.set(tree.definition, tree);
	const name = nominalRefinementCheck(tree);
	// Keep existing Fin-only generated bytes; result-only Subtypes need no checked converter.
	if(checked || name === "check")
	{
		if(!checks.has(tree.definition)) checks.set(tree.definition, new Map());
		const selected = checks.get(tree.definition);
		if(selected.has(name) && canonicalJson(selected.get(name)) !== canonicalJson(tree))
			throw new TypeError(`Conflicting nominal checked conversions: ${tree.definition}.${name}`);
		selected.set(name, tree);
	}
}
if(tree.kind === "checked-record" && checked && tree.constructor !== null)

// Callback arguments cross in the opposite direction; the callback result crosses back.
if(tree.kind === "callback")
{
	tree.parameters.forEach(child => walk(child, !checked));
	walk(tree.result, checked);
}
else for(const child of refinementChildren(tree)) walk(child, checked);

for(const item of model.exports) if(item.refinements)
{
	item.refinements.parameters.forEach(tree => walk(tree, true));
	walk(item.refinements.result, false);
}

